:root {
  color-scheme: dark;
  --night: #202344;
  --panel: #2b2f54;
  --panel-light: #363b66;
  --cream: #f6f0dc;
  --muted: #b7bad0;
  --mint: #8ee3c2;
  --coral: #ff9b83;
}
* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 40px 16px;
  display: grid;
  place-items: center;
  background-color: var(--night);
  background-image: radial-gradient(#41466f 1px, transparent 1px);
  background-size: 20px 20px;
  color: var(--cream);
  font: 16px/1.5 system-ui, sans-serif;
}
button, input { font: inherit; }
.board {
  width: min(100%, 640px);
  padding: clamp(22px, 6vw, 42px);
  background: var(--panel);
  border: 2px solid #555a84;
  box-shadow: 8px 8px 0 #171a36;
}
.header { display: flex; align-items: center; gap: 18px; }
.pixel-clock {
  width: 60px; height: 60px; display: grid; place-items: center;
  color: var(--night); background: var(--mint); border: 4px solid var(--cream);
  box-shadow: 4px 4px 0 #171a36; font-size: 38px; line-height: 1;
}
.eyebrow, footer { margin: 0; color: var(--mint); font-size: 12px; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 1px 0 0; font-size: clamp(27px, 7vw, 36px); line-height: 1.15; letter-spacing: -.04em; }
.summary {
  display: flex; align-items: center; gap: 9px; margin: 28px 0 30px; padding: 13px 15px;
  background: #242849; border-left: 4px solid var(--mint); color: var(--muted);
}
.summary strong { color: var(--cream); font-size: 20px; }
.summary-dot { width: 9px; height: 9px; flex: 0 0 auto; background: var(--mint); box-shadow: 0 0 0 3px #8ee3c233; }
.summary-note { margin-left: auto; font-size: 14px; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
legend, h2 { font-size: 18px; font-weight: 750; }
legend { margin-bottom: 12px; }
.form-grid { display: grid; grid-template-columns: minmax(64px, 1fr) 10px minmax(64px, 1fr) minmax(120px, 2fr) auto; align-items: end; gap: 10px; }
.time-field, .label-field { display: grid; gap: 6px; color: var(--muted); font-size: 14px; font-weight: 650; }
.time-field input, .label-field input {
  width: 100%; min-width: 0; height: 46px; padding: 8px 10px; color: var(--cream);
  background: #202344; border: 2px solid #555a84; border-radius: 0; outline: none;
}
.time-field input { text-align: center; font-size: 19px; font-weight: 750; }
input::placeholder { color: #8589a8; opacity: 1; }
input:focus-visible, button:focus-visible { outline: 3px solid var(--mint); outline-offset: 3px; }
.colon { align-self: center; padding-top: 21px; color: var(--mint); font-weight: 800; }
.optional { font-weight: 400; }
.add-button, .toggle, .delete-button {
  min-height: 44px; border: 2px solid transparent; border-radius: 0; cursor: pointer; font-weight: 750;
  transition: transform .12s ease, filter .12s ease, background-color .12s ease;
}
.add-button { padding: 0 14px; color: var(--night); background: var(--mint); box-shadow: 3px 3px 0 #171a36; white-space: nowrap; }
.add-button span { font-size: 20px; vertical-align: -1px; }
button:hover { filter: brightness(1.12); }
button:active { transform: translate(2px, 2px); box-shadow: none; }
.list-section { margin-top: 34px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
h2 { margin: 0; }
.sort-note { color: var(--muted); font-size: 13px; }
.alarm-list { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }
.alarm-row { display: flex; align-items: center; gap: 12px; min-height: 68px; padding: 10px 12px; background: var(--panel-light); border: 1px solid #555a84; }
.alarm-row.is-off { opacity: .58; }
.alarm-time { min-width: 94px; color: var(--cream); font-size: 25px; font-weight: 800; letter-spacing: .04em; font-variant-numeric: tabular-nums; }
.alarm-label { overflow: hidden; flex: 1; color: var(--muted); text-overflow: ellipsis; white-space: nowrap; }
.toggle { min-width: 70px; padding: 6px 10px; color: var(--night); background: var(--mint); }
.toggle[aria-pressed="false"] { color: var(--cream); background: #555a84; }
.delete-button { width: 40px; padding: 0; color: var(--coral); background: transparent; border-color: #696d91; font-size: 20px; }
.delete-button:hover { color: var(--night); background: var(--coral); }
.empty-state { margin: 0; padding: 20px 12px; color: var(--muted); text-align: center; border: 1px dashed #62668c; }
.empty-state span { color: var(--mint); }
.form-message { min-height: 24px; margin: 8px 0 0; color: var(--coral); font-size: 14px; }
footer { margin-top: 28px; text-align: center; color: var(--muted); font-size: 11px; }
footer span { color: var(--mint); }
@media (max-width: 520px) {
  body { padding: 20px 12px; }
  .form-grid { grid-template-columns: minmax(64px, 1fr) 8px minmax(64px, 1fr); gap: 9px; }
  .label-field { grid-column: 1 / 3; }
  .add-button { grid-column: 3; align-self: end; padding-inline: 8px; }
  .summary-note { display: none; }
  .alarm-row { gap: 8px; padding-inline: 8px; }
  .alarm-time { min-width: 84px; font-size: 23px; }
  .toggle { min-width: 62px; padding-inline: 7px; }
}

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const alarmList = document.querySelector('#alarm-list');
const enabledCount = document.querySelector('#enabled-count');
const emptyState = document.querySelector('#empty-state');
const formMessage = document.querySelector('#form-message');
let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute) || a.id - b.id);
  alarmList.replaceChildren();
  alarms.forEach((alarm) => {
    const row = document.createElement('li');
    row.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;

    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;

    const label = document.createElement('span');
    label.className = 'alarm-label';
    label.textContent = alarm.label || 'No label';

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'toggle';
    toggle.textContent = alarm.enabled ? 'On' : 'Off';
    toggle.setAttribute('aria-pressed', String(alarm.enabled));
    toggle.setAttribute('aria-label', `${alarm.enabled ? 'Turn off' : 'Turn on'} ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    toggle.addEventListener('click', () => {
      alarm.enabled = !alarm.enabled;
      render();
    });

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter((item) => item.id !== alarm.id);
      render();
    });

    row.append(time, label, toggle, remove);
    alarmList.append(row);
  });
  enabledCount.textContent = String(alarms.filter((alarm) => alarm.enabled).length);
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) {
    formMessage.textContent = 'Enter an hour from 0–23 and a minute from 0–59.';
    return;
  }
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  formMessage.textContent = '';
  form.reset();
  render();
  hourInput.focus();
});

render();
